function Name([type]$t){if($t.IsByRef){return (Name $t.GetElementType())+'&'};if($t.IsPointer){return (Name $t.GetElementType())+'*'};if($t.IsArray){return (Name $t.GetElementType())+'[]'};if($t.IsGenericType){return $t.GetGenericTypeDefinition().FullName+'<'+((@($t.GetGenericArguments()|ForEach-Object{Name $_})) -join ',')+'>'};return $t.FullName}
function Failure($r){$e=$r.Exception;while($e.InnerException){$e=$e.InnerException};$f=[ordered]@{type=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$f.index=$e.Index;$f.charUnknown=[int]$e.CharUnknown;$f.high=[int]$e.CharUnknownHigh;$f.low=[int]$e.CharUnknownLow;$f.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$f.index=$e.Index;$f.bytes=[int[]]@($e.BytesUnknown|ForEach-Object{[int]$_})};if($e -is [ArgumentOutOfRangeException]){$f.actualValue=$e.ActualValue};return $f}
$type=[Text.UnicodeEncoding];$declared=[Reflection.BindingFlags]'Public,Instance,Static,DeclaredOnly';$methods=@($type.GetMethods($declared)|ForEach-Object{[ordered]@{name=$_.Name;returnType=(Name $_.ReturnType);parameters=@($_.GetParameters()|ForEach-Object{[ordered]@{name=$_.Name;type=(Name $_.ParameterType)}});isVirtual=$_.IsVirtual;isFinal=$_.IsFinal}}|Sort-Object {($_|ConvertTo-Json -Depth 10 -Compress)})
$constructors=@($type.GetConstructors()|ForEach-Object{,@($_.GetParameters()|ForEach-Object{[ordered]@{name=$_.Name;type=(Name $_.ParameterType)}})})
$encodings=[Collections.Generic.List[Text.UnicodeEncoding]]::new();$specs=[Collections.Generic.List[object]]::new()
foreach($kind in 0..8){$big=$false;$bom=$true;$strict=$false;if($kind -eq 0){$owner=[Text.UnicodeEncoding]::new()}else{$bits=$kind-1;$big=($bits -band 4) -ne 0;$bom=($bits -band 2) -ne 0;$strict=($bits -band 1) -ne 0;$owner=[Text.UnicodeEncoding]::new($big,$bom,$strict)};foreach($custom in @($false,$true)){if($custom){$owner=[Text.UnicodeEncoding]$owner.Clone();$owner.EncoderFallback=[Text.EncoderReplacementFallback]::new('AB');$owner.DecoderFallback=[Text.DecoderReplacementFallback]::new('CD')};$encodings.Add($owner);$preamble=$owner.GetPreamble();$specs.Add([ordered]@{constructor=$kind;bigEndian=$big;bom=$bom;strict=$strict;custom=$custom;codePage=$owner.CodePage;readOnly=$owner.IsReadOnly;webName=$owner.WebName;encodingName=$owner.EncodingName;singleByte=$owner.IsSingleByte;encoderFallback=$owner.EncoderFallback.GetType().FullName;decoderFallback=$owner.DecoderFallback.GetType().FullName;encoderMax=$owner.EncoderFallback.MaxCharCount;decoderMax=$owner.DecoderFallback.MaxCharCount;encoderHash=$owner.EncoderFallback.GetHashCode();decoderHash=$owner.DecoderFallback.GetHashCode();hash=$owner.GetHashCode();preamble=[int[]]@($preamble|ForEach-Object{[int]$_});preambleIdentity=[object]::ReferenceEquals($preamble,$owner.GetPreamble())})}}
