 EA=$type.GetMethod('GetBytes',[type[]]@([char[]],[int],[int],[byte[]],[int]));ES=$type.GetMethod('GetBytes',[type[]]@([string],[int],[int],[byte[]],[int]));DA=$type.GetMethod('GetChars',[type[]]@([byte[]],[int],[int],[char[]],[int]));CB=$type.GetMethod('GetByteCount',[type[]]@([char[]],[int],[int]));CC=$type.GetMethod('GetCharCount',[type[]]@([byte[]],[int],[int]));ST=$type.GetMethod('GetString',[type[]]@([byte[]],[int],[int]));WB=$type.GetMethod('GetByteCount',[type[]]@([char[]]));WG=$type.GetMethod('GetCharCount',[type[]]@([byte[]]));EB=$type.GetMethod('GetBytes',[type[]]@([char[]]));DC=$type.GetMethod('GetChars',[type[]]@([byte[]]));DS=$type.GetMethod('GetString',[type[]]@([byte[]]));SB=$type.GetMethod('GetByteCount',[type[]]@([string]));SE=$type.GetMethod('GetBytes',[type[]]@([string]))
}
function Snapshot($value){if($null -eq $value){return $null};return ,([int[]]@($value|ForEach-Object{[int]$_}))}
function Record-Call($Owner,[int]$State,[string]$Operation,$Source,[int]$Index,[int]$Count,$Destination,[int]$OutputIndex,[string]$Group,[int]$Form){
 $argumentCount=if($Operation -in @('EA','ES','DA')){5}elseif($Operation -in @('CB','CC','ST')){3}else{1};$argsList=[object[]]::new($argumentCount)
 $argsList[0]=$Source;if($Operation -in @('ES','SB','SE') -and $null -ne $Source){$argsList[0]=[string]::new([char[]]$Source)};if($argsList.Length -ge 3){$argsList[1]=$Index;$argsList[2]=$Count};if($argsList.Length -eq 5){$argsList[3]=$Destination;$argsList[4]=$OutputIndex}
 $result=$null;$failure=$null;try{$actual=$methods[$Operation].Invoke($Owner,$argsList);$result=if($actual -is [string]){Snapshot $actual.ToCharArray()}elseif($actual -is [Array]){Snapshot $actual}else{$actual}}catch{$failure=Failure $_}
 return [ordered]@{state=$State;operation=$Operation;group=$Group;form=$Form;input=(Snapshot $Source);index=$Index;count=$Count;outputIndex=$OutputIndex;buffer=(Snapshot $Destination);result=$result;failure=$failure}
}
$encodeInputs=@(@(65),@(55357,56832),@(55296),@(65,55296,66),@(55296,56320,65),@(55296,55296),@(65,0,65535));$decodeInputs=@(@(65,0),@(0,65),@(0,216,0,220),@(216,0,220,0),@(0,216,65),@(0,216,65,0),@(65,0,216,0),@(65),@(255,255,0));$rows=[Collections.Generic.List[object]]::new()
foreach($i in 0..($encodings.Count-1)){$owner=$encodings[$i];foreach($operation in @('EA','ES','DA')){$inputsList=if($operation -eq 'DA'){,$decodeInputs}else{,$encodeInputs};foreach($units in $inputsList){foreach($capacity in @(0,1,2,3,4,5,6,7,8,16)){$source=if($operation -eq 'DA'){,[byte[]](@(33)+$units+@(35))}else{,[char[]](@(33)+$units+@(35))};$destination=if($operation -eq 'DA'){,[char[]]('#'*($capacity+1))}else{,[byte[]](@(170)*($capacity+1))};$rows.Add((Record-Call $owner $i $operation $source 1 $units.Length $destination 1 'capacity' 0))}}
 foreach($form in 0..15){$source=if($operation -eq 'DA'){,[byte[]]@(33,65,0,66,35)}else{,[char[]]@(33,65,55296,66,35)};$destination=if($operation -eq 'DA'){,[char[]]('#'*16)}else{,[byte[]](@(170)*16)};$index=1;$count=3;$outputIndex=1
  switch($form){0{$source=$null}1{$destination=$null}2{$index=-1}3{$count=-1}4{$index=6}5{$count=6}6{$outputIndex=-1}7{$outputIndex=17}8{$source=$null;$destination=$null}9{$index=-1;$outputIndex=-1}10{$index=[int]::MaxValue}11{$outputIndex=[int]::MaxValue}12{$count=[int]::MaxValue}13{$index=5;$count=0;$outputIndex=16}14{$index=-1;$destination=$null}15{$source=$null;$outputIndex=-1}}
  $rows.Add((Record-Call $owner $i $operation $source $index $count $destination $outputIndex 'validation' $form))
 }
}
 foreach($operation in @('CB','CC','ST')){foreach($form in 0..8){$source=if($operation -eq 'CB'){,[char[]]@(33,65,55296,66,35)}else{,[byte[]]@(33,65,0,66,35)};$index=1;$count=3
  switch($form){0{$source=$null}1{$index=-1}2{$count=-1}3{$index=6}4{$count=6}5{$index=-1;$count=-1}6{$index=[int]::MaxValue}7{$count=[int]::MaxValue}8{$index=5;$count=0}}
  $rows.Add((Record-Call $owner $i $operation $source $index $count $null 0 'count-validation' $form))
 }}
 foreach($operation in @('WB','WG','EB','DC','DS','SB','SE')){$rows.Add((Record-Call $owner $i $operation $null 0 0 $null 0 'whole-null' 0))}
}
